package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class Attribute_setValue_TriageGen1Test {

    @Test
    public void testSetValue_NullParameter() {
        // Arrange
        Attribute attribute = new Attribute("key", "value", null);
        String oldValue = attribute.setValue(null);

        // Assert
        assertNull(oldValue);
        assertEquals("value", attribute.val);
    }

    @Test
    public void testSetValue_ValidParameter() {
        // Arrange
        Attribute attribute = new Attribute("key", "value", null);
        String oldValue = attribute.setValue("newValue");

        // Assert
        assertEquals("value", oldValue);
        assertEquals("newValue", attribute.val);
    }

    @Test
    public void testSetValue_NullParent() {
        // Arrange
        Attribute attribute = new Attribute("key", "value", null);
        String oldValue = attribute.setValue("newValue");

        // Assert
        assertEquals("value", oldValue);
        assertEquals("newValue", attribute.val);
    }

    @Test
    public void testSetValue_ValidParent() {
        // Arrange
        Attributes parent = new Attributes();
        Attribute attribute = new Attribute("key", "value", parent);
        String oldValue = attribute.setValue("newValue");

        // Assert
        assertEquals("value", oldValue);
        assertEquals("newValue", attribute.val);
    }

    @Test
    public void testSetValue_ValidParentAndKey() {
        // Arrange
        Attributes parent = new Attributes();
        parent.put("key", "value");
        Attribute attribute = new Attribute("key", "value", parent);
        String oldValue = attribute.setValue("newValue");

        // Assert
        assertEquals("value", oldValue);
        assertEquals("newValue", attribute.val);
    }

    @Test
    public void testSetValue_ValidParentAndKeyAndIndex() {
        // Arrange
        Attributes parent = new Attributes();
        parent.put("key", "value");
        Attribute attribute = new Attribute("key", "value", parent);
        String oldValue = attribute.setValue("newValue");

        // Assert
        assertEquals("value", oldValue);
        assertEquals("newValue", attribute.val);
    }

    @Test
    public void testSetValue_NullParentAndKey() {
        // Arrange
        Attribute attribute = new Attribute("key", "value", null);
        String oldValue = attribute.setValue("newValue");

        // Assert
        assertEquals("value", oldValue);
        assertEquals("newValue", attribute.val);
    }

    @Test
    public void testSetValue_NullParentAndKeyAndIndex() {
        // Arrange
        Attribute attribute = new Attribute("key", "value", null);
        String oldValue = attribute.setValue("newValue");

        // Assert
        assertEquals("value", oldValue);
        assertEquals("newValue", attribute.val);
    }
}
